type ProductOption = {
  id: number;
  name: string;
  product_code?: string;
  base_price?: string;
  category?: string;
  subcategory?: string;
  is_emi_enabled?: boolean;
  is_rent_enabled?: boolean;
  is_lease_enabled?: boolean;
  is_direct_sale_enabled?: boolean;
  lifecycle_status?: string;
  on_hand_qty?: string;
  reserved_qty?: string;
  available_qty?: string;
  stock_status?: "IN_STOCK" | "LOW_STOCK" | "OUT_OF_STOCK" | "FULLY_RESERVED";
};

type PartnerOption = {
  id: number;
  username?: string;
  phone?: string;
};

const [product, setProduct] = useState<ProductOption | null>(null);
const [productQuery, setProductQuery] = useState("");
const [productResults, setProductResults] = useState<ProductOption[]>([]);
const [productLoading, setProductLoading] = useState(false);

const [partner, setPartner] = useState<PartnerOption | null>(null);
const [partnerQuery, setPartnerQuery] = useState("");
const [partnerResults, setPartnerResults] = useState<PartnerOption[]>([]);
const [partnerLoading, setPartnerLoading] = useState(false);

const runProductSearch = useCallback(async () => {
  if (!productQuery.trim()) {
    setProductResults([]);
    return;
  }
  setProductLoading(true);
  try {
    const payload = await apiFetch<unknown>(`/admin/products/search/?q=${productQuery.trim()}`);
    const normalized = toArray<Record<string, unknown>>(payload).map(normalizeProduct);
    const filtered = normalized.filter((item) => {
      if (item.lifecycle_status === "DISCONTINUED") return false;
      if (planType === "EMI") return Boolean(item.is_emi_enabled);
      if (planType === "RENT") return Boolean(item.is_rent_enabled);
      if (planType === "LEASE") return Boolean(item.is_lease_enabled);
      return true;
    });
    if (!cancelled) setProductResults(filtered);
  } catch {
    if (!cancelled) setProductResults([]);
  } finally {
    if (!cancelled) setProductLoading(false);
  }
}, [productQuery, planType]);

const runPartnerSearch = useCallback(async () => {
  if (!partnerQuery.trim()) {
    setPartnerResults([]);
    return;
  }
  setPartnerLoading(true);
  try {
    const payload = await apiFetch<unknown>(`/admin/partners/?q=${partnerQuery.trim()}`);
    const normalized = toArray<Record<string, unknown>>(payload).map(normalizePartner);
    if (!cancelled) setPartnerResults(normalized);
  } catch {
    if (!cancelled) setPartnerResults([]);
  } finally {
    if (!cancelled) setPartnerLoading(false);
  }
}, [partnerQuery]);

useEffect(() => {
  const t = setTimeout(() => {
    if (productQuery.trim()) {
      void runProductSearch();
    } else {
      setProductResults([]);
    }
  }, 400);
  return () => clearTimeout(t);
}, [productQuery, runProductSearch]);

useEffect(() => {
  const t = setTimeout(() => {
    if (partnerQuery.trim()) {
      void runPartnerSearch();
    } else {
      setPartnerResults([]);
    }
  }, 400);
  return () => clearTimeout(t);
}, [partnerQuery, runPartnerSearch]);

setProductQuery("");
setBatchQuery("");
setLuckyQuery("");
setPartnerQuery("");

setProductResults([]);
setBatchResults([]);
setLuckyResults([]);
setPartnerResults([]);

